#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/doppler/tasks/setup-secrets-doppler.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Select the Doppler project and config of this repository"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def main():
  root = os.environ["MISE_PROJECT_ROOT"]
  # A repository without a doppler.yaml has no Doppler project to select.
  if not os.path.isfile(f"{root}/doppler.yaml"):
    return 0

  helpers.print_header("Setting up the secrets with Doppler ...")

  if not helpers.has_tool("doppler"):
    helpers.print_warn("doppler is not on PATH — skipping secrets setup.")
    helpers.print_yellow("Install the repo's pinned tools with 'mise install', then re-run this task.")
    return 0

  # `doppler login` opens a browser, so this task does not run it.
  me = helpers.tool("doppler", "me", stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
  if me.returncode != 0:
    helpers.print_warn("Not logged in to Doppler — skipping secrets setup.")
    helpers.print_yellow("Run 'mise x -- doppler login', then re-run this task.")
    return 0

  # doppler reads ./doppler.yaml, so it runs from the repository root. Without
  # prompts, it takes the project and config from that file.
  os.chdir(root)
  return helpers.tool("doppler", "setup", "--no-interactive").returncode


if __name__ == "__main__":
  sys.exit(main())
